      "given": "Benzaldehyde ($C_6H_5CHO$) with $50\\% KOH$ under heating.",
      "formula": "$2C_6H_5CHO + KOH \\rightarrow C_6H_5CH_2OH + C_6H_5COOK$",
      "stepByStep": "1. Aldehydes lacking alpha-hydrogen atoms (such as benzaldehyde, formaldehyde, and trimethylacetaldehyde) cannot form an enolate ion required for aldol condensation.\n2. In the presence of concentrated alkali, nucleophilic addition of $OH^-$ produces a tetrahedral dianion intermediate.\n3. Hydride ion ($H^-$) is directly transferred from this intermediate to a second molecule of benzaldehyde (rate-determining step).\n4. This results in self-oxidation-reduction (disproportionation): one molecule of benzaldehyde is reduced to benzyl alcohol ($C_6H_5CH_2OH$), while the other is oxidized to benzoate salt ($C_6H_5COOK$).",
